/* ==================== DESKTOP (≥ 1280px) - PULSANTI IDENTICI A MOBILE ==================== */
@media (min-width: 1280px) {
  .header-row {
    position: static;
    background: transparent;
    box-shadow: none;
    height: auto;           
    min-height: 100px;       
    padding-top: 90px;      
    padding-left: 12%;      
    padding-right: 12%;     
    margin-bottom: 0px;    
    justify-content: space-between;
    pointer-events: auto;
  }

  .title-group { 
    padding-left: 0; 
    padding-right: 0;
    background: transparent;
    border: none;
    box-shadow: none;
    position: static;
    cursor: default;
  }

  .title { 
    font-size: 36px;           
    font-weight: 700;          
    color: #f8fafc;            
    margin: 0 0 8px 0;
  }

  .subtitle { 
    font-size: 24px;           
    color: #67e8f9; 
    font-weight: 600;
    display: block;
    margin-bottom: 6px;
  }

  .sources {
    font-size: 15px;         
    color: #94a3b8;
    display: block;
  }

  /* Pulsanti identici a mobile (stesso stile, stesse icone) */
  .actions {
    position: static !important;
    display: flex !important;
    flex-direction: row !important;
    gap: 12px !important;
    align-items: center !important;
  }

  /* Nessuna riduzione di dimensione - esattamente come mobile */
  .btn { 
    padding: 9px;           
  }
  .btn svg { 
    width: 24px;             
    height: 24px;            
  }
  .btn.nav-btn { 
    color: #67e8f9; 
    padding: 7px 10px;       
  }
  .btn.nav-btn svg { 
    width: 26px;             
    height: 26px;            
    stroke: currentColor; 
    stroke-width: 2.5; 
    fill: none; 
  }

  #full-capture-area {
    padding: 15px;
  }

  .chart-container {
    justify-content: center;
    align-items: flex-start;
    padding-bottom: 60px;
  }

  .chart-container img {
    max-width: 90%;
    max-height: 100%;
  }
}
